 page('guide-'+slug+'.html',t,d,hero(t.upper(),d,c)+section('<div class="prose">'+notice('Guide draft for review. Approved server rules take precedence.')+''.join('<p style="margin-top:22px">'+E(p)+'</p>' for p in text.split('\n\n'))+'<div class="button-row" style="margin-top:30px">'+btn('Back to Core Hub','core-hub.html')+'</div></div>'))
