build_lspd(page, icon, btn)

DEPARTMENT_CONCEPTS=[
    ('LSPD','Los Santos Police Department','City policing and public-service stories.',(584,532,132,89),'shield'),
    ('BCSO',"Blaine County Sheriff’s Office",'County communities and the roads between them.',(733,532,135,89),'shield'),
    ('SASP','San Andreas State Police','A statewide law-enforcement identity.',(880,536,151,87),'shield'),
    ('FMA','Fire & Medical Authority','Emergency response and patient-care stories.',(582,634,139,79),'pulse'),
    ('DOJ','Department of Justice','The legal and judicial side of the city.',(724,626,148,92),'building'),
    ('ICO','Internal Community Operations','A proposed home for internal community functions.',(874,632,168,86),'people'),
]
def department_concepts():
    cards=''
    for code,title,desc,rect,ico in DEPARTMENT_CONCEPTS:
        art=reference_slice(*rect,'department-reference')
        url,label=('department-lspd.html','Explore LSPD') if code=='LSPD' else ('guide-departments.html','About department pathways')
        category='DEPARTMENT OVERVIEW' if code=='LSPD' else 'BRAND-REFERENCE CONCEPT'
        cards+=f'<article class="card department-card"><div class="department-identity">{art}<span class="department-fallback">{E(code)}</span></div><span class="category">{category}</span><h3>{E(title)}</h3><p>{E(desc)}</p><a class="text-link" href="{url}">{label} {icon("arrow")}</a></article>'
    return '<div class="grid-3 department-grid">'+cards+'</div>'
page('departments.html','Departments','Explore the department identities proposed in Cosmic’s brand reference.',hero('A CITY WORTH SERVING.','Different callings. A shared community. Discover the public-service side of Cosmic.','Departments')+section(notice('<b>Proposed identities, not an active roster.</b> These six concepts come from the brand reference. Names, responsibilities, access, and recruitment still require confirmation. No applications are announced as open.')+department_concepts())+section('<div class="grid-2">'+card('Public information','Confirmed introductions, recruitment details, and approved public documents will have a home here.','book','guide-departments.html','Explore department pathways')+card('Internal resources','Open your department’s private notices and employee roster after Discord role verification.','lock','portal.html#departments','Open My departments')+'</div>','compact'))

page('businesses.html','Businesses','Discover player businesses and proposal pathways in Cosmic.',hero('PUT YOUR NAME ON IT.','Create a reason for people to stop, stay, and come back. Business ownership starts with a story worth sharing.','Businesses','<div class="button-row">'+btn('Submit a proposal','portal.html#requests',True)+btn('Read the business guide','guide-business.html')+'</div>')+section('<div class="grid-2">'+card('Established businesses','Existing locations can be listed here once their ownership and availability are confirmed. No prices, vacancies, or purchase options are assumed.','building')+card('Original ideas','Pitch a new concept with its purpose, preferred location, staffing plan, and the roleplay it creates. Approval depends on the concept and server compatibility.','briefcase')+'</div>')+section('<div class="section-head"><div><span class="eyebrow">Business directory</span><h2>THE PEOPLE BEHIND THE COUNTER.</h2></div></div><div id="business-directory" class="grid-3"></div><div class="empty-state" id="business-empty">'+icon('briefcase')+'<h3>Confirmed businesses will be listed here.</h3><p>Only approved listings should appear in the directory. Businesses can be added through the public content file after owner review.</p></div>','compact'))
page('organizations.html','Organizations','Find Cosmic’s clubs, crews, and organization proposal area.',hero('FIND YOUR CIRCLE.','A shared identity. A common purpose. People who turn a character’s story into something bigger.','Organizations','<div class="button-row">'+btn('Propose an organization','portal.html#requests',True)+btn('Read the organization guide','guide-organizations.html')+'</div>')+section('<div class="grid-3">'+card('Clubs & communities','Gather around a shared interest, a social space, or a cause your characters care about.','people')+card('Crews & collectives','Build an identity through shared projects, events, and the roleplay you create with others.','grid')+card('Criminal organizations','Concepts and activities require staff approval and must follow the final criminal-roleplay and organization rules.','shield')+'</div>')+section('<div class="section-head"><div><span class="eyebrow">Organization directory</span><h2>A NAME THAT MEANS SOMETHING.</h2></div></div><div id="organization-directory" class="grid-3"></div><div class="empty-state" id="organization-empty">'+icon('people')+'<h3>Official organizations will appear here.</h3><p>No group is presented as approved, active, or recruiting until its listing has been confirmed.</p></div>','compact'))
page('media.html','Media','The home for approved Cosmic screenshots, trailers, and community creations.',hero('THE CITY, THROUGH YOUR EYES.','Moments worth keeping. Characters worth remembering. A place for the community’s view of Cosmic.','Media')+section('<div class="section-head"><div><span class="eyebrow">From the community</span><h2>MAKE A MOMENT OF IT.</h2></div><p>Real server screenshots and approved videos can replace these media slots when the new branding is ready.</p></div><div id="media-gallery" class="grid-2"></div><div id="media-placeholders" class="grid-2">'+''.join(f'<div class="media-slot">{icon("camera")}<strong>{t}</strong><small>Awaiting approved community media</small></div>' for t in ['The city after dark','The people who make it home'])+'</div>')+section('<div class="grid-2">'+card('Share your perspective','Members can send creator inquiries through the portal. This release records text requests and does not accept direct media uploads.','camera','portal.html#requests','Open requests')+card('Official channels','Official social channels are connected only after the community supplies the correct links.','discord')+'</div><div class="button-row" style="margin-top:25px">'+btn('YouTube',attr='data-link="youtube"')+btn('Twitch',attr='data-link="twitch"')+btn('Discord',attr='data-link="discord"')+'</div>','compact'))
NEWS=[('rebrand','Same name. A new chapter.','Cosmic is preparing a refreshed visual identity.','The name is staying Cosmic. The visual identity is changing.\n\nThis website is using a provisional charcoal, silver, and ice-blue direction inspired by the supplied city-themed brand reference. Its colors, logo, and key images are configurable so the final identity can be applied consistently.\n\nThis article is draft announcement copy. The team should approve its wording and add a publication date before using it as official news.'),('whitelist','A whitelisted future.','A clear route from your first visit to community membership.','Cosmic is planning a move to whitelisted access.\n\nThe new portal separates account creation, application review, and approved membership. Applicants can follow their progress and read feedback without confusing a login with permission to enter the server.\n\nNo launch date, eligibility threshold, or review turnaround is announced by this draft. The team will publish confirmed requirements and open submissions when ready.'),('portal','Your community, connected.','Public information and member tools in one home.','The website brings Home, About, Community, Join, Rules, Core Hub, Departments, Businesses, Organizations, Media, News, and Status together.\n\nThe member side is designed around applications, private resources, requests, and account settings, with a separate review workspace for authorized staff.\n\nThis is preview copy for an unlaunched system. Connected services and permissions must be configured and tested before real member information is collected.')]
page('news.html','News','News and announcements from Cosmic. Current articles are editorial previews.',hero('FROM THE TEAM.','Community news, development notes, and the next chapter of Cosmic.','News & announcements')+section(notice('<b>Editorial previews.</b> The articles below are draft announcement copy, not dated releases or a claim that the portal is live.')+'<div class="grid-3" style="margin-top:28px">'+''.join(f'<a class="card news-card" href="news-{s}.html"><div class="news-art"><span class="news-cityline" aria-hidden="true"></span><span class="display">{a}</span></div><span class="meta">DRAFT / NOT YET PUBLISHED</span><h3>{t}</h3><p>{d}</p><span class="text-link">Read preview {icon("arrow")}</span></a>' for (s,t,d,b),a in zip(NEWS,['COSMIC','ACCESS','HUB']))+'</div>'))
for s,t,d,b in NEWS:
 page('news-'+s+'.html',t,d,hero(t.upper(),d,'Editorial preview')+section('<article class="prose">'+notice('Draft announcement. Publication date and final wording await team approval.')+''.join('<p style="margin-top:24px">'+E(p)+'</p>' for p in b.split('\n\n'))+'<div class="button-row" style="margin-top:30px">'+btn('Back to news','news.html')+'</div></article>'))
page('status.html','Status','See verified service status when an official monitoring endpoint is connected.',hero('KEEP UP WITH THE CITY.','Connection information and service updates, without guesswork.','Service status')+section('<div class="status-stack"><div class="status-row"><div><h3>FiveM game server</h3><p id="status-detail">No official monitoring endpoint has been connected.</p></div><span class="pill" id="server-status">Status unavailable</span></div><div class="status-row"><div><h3>Whitelist applications</h3><p>Intake is controlled by the team in the authenticated portal.</p></div><a class="pill" href="portal.html#apply">Check portal</a></div><div class="status-row"><div><h3>Community Discord</h3><p>This page does not independently monitor Discord availability.</p></div><button class="button small" data-link="discord">Open Discord ↗</button></div></div><p class="muted-text" id="status-time" style="margin-top:16px">No live player count or uptime data is displayed until verified.</p><div class="button-row" style="margin-top:25px"><button class="button" id="refresh-status">Refresh status '+icon('pulse')+'</button></div>')+section('<div class="empty-state">'+icon('pulse')+'<h3>Incident reporting is not connected.</h3><p>This build has no incident-history service. Absence of an incident here does not mean every service is online.</p></div>','compact'))
page('login.html','Member login','Sign in to your Cosmic account using Discord.',f'<div class="wrap"><section class="auth-layout"><div class="auth-copy"><span class="eyebrow">The Cosmic portal</span><h1>YOUR COMMUNITY.<br>ONE CONNECTION.</h1><p>Save your application, follow your progress, and find the tools that come with being part of Cosmic.</p><p class="muted-text">Signing in creates an applicant account. Whitelist membership is reviewed separately.</p></div><div class="auth-card"><h2>Welcome to Cosmic.</h2><p>Use your Discord account to continue. New here? Your portal account is created on your first successful sign-in.</p>{btn('Continue with Discord',primary=True,attr='id="discord-login"')}<div id="auth-notice" class="notice">Checking account connection...</div><p id="auth-message" class="message" aria-live="polite"></p><p class="tiny">You will authenticate on Discord’s official site. Never enter your Discord password into a Cosmic form. Read our <a href="privacy.html"><u>privacy information</u></a> before continuing.</p><a href="portal-preview.html" class="text-link" data-design-preview style="margin-top:20px">View the read-only portal design ↗</a></div></section></div>')
page('auth-callback.html','Completing sign-in','Complete your Discord sign-in and return to Cosmic.',section('<div class="portal-load"><h2>CONNECTING YOUR ACCOUNT.</h2><p id="auth-notice">Completing your sign-in securely...</p><p id="auth-message" class="message" aria-live="polite"></p><div class="button-row">'+btn('Return to login','login.html')+'</div></div>'))
def portal_shell(preview=False):
 banner='<div class="preview-banner"><span><b>DESIGN PREVIEW.</b> Fictional sample account. Read-only. This is not a login or real member data.</span><label for="preview-role">Preview role <select id="preview-role"><option value="applicant">Applicant</option><option value="member" selected>Approved member</option><option value="staff">Staff reviewer</option></select></label></div>' if preview else ''
 return banner+f'<header class="portal-bar">{brand()}<div class="right"><span class="pill">MEMBER PORTAL</span><a href="index.html">Back to website ↗</a><button class="button small" id="sign-out"'+(' hidden' if preview else '')+f'>Sign out</button></div></header><div id="portal-root"><main id="main" class="portal-load"><h1>{"PORTAL DESIGN PREVIEW" if preview else "YOUR COSMIC ACCOUNT"}</h1><p>{"Loading the read-only preview..." if preview else "Checking your session and permissions..."}</p></main></div>'
page('portal.html','Member portal','Your Cosmic account, applications, requests, and private resources.',portal_shell(),portal=True)
page('portal-preview.html','Portal design preview','Read-only layout preview with fictional sample data. Not a real account or authentication.',portal_shell(True),portal=True,preview=True)
page('privacy.html','Privacy & data','What this build stores, what still needs owner configuration, and how to request assistance.',hero('YOUR ACCOUNT. YOUR INFORMATION.','A clear view of the data this portal is designed to use.','Privacy information')+section('<article class="prose">'+notice('<b>Pre-launch information, not a finalized privacy notice.</b> The community owner must add the operator’s identity, contact route, retention policy, applicable rights, and service details before collecting real applications.')+'<h2>PUBLIC WEBSITE</h2><p>The public site includes no advertising, analytics SDK, or tracking pixel. Your hosting provider may maintain access logs. External destinations have their own policies.</p><h2>AUTHENTICATION</h2><p>When configured, Discord handles identity sign-in through Supabase. The browser stores an authentication session needed to keep you signed in. Signing out removes the active local session. Cosmic does not collect your Discord password.</p><h2>PORTAL RECORDS</h2><p>The backend stores your user ID, display name, account access role, application answers, review feedback, and application workflow history. Supabase Auth may also hold profile or email information supplied by Discord. Do not enter passwords, payment details, or unnecessary real-world personal information into an application.</p><h2>DISCORD APPLICATION REVIEWS</h2><p>Submitted application answers, your display name, verified Discord user ID, application status, and staff feedback are shared with authorized reviewers in a private Cosmic Discord channel. Drafts are not sent to Discord. Staff can approve, deny, or request changes there; their feedback is visible to you in the portal. Discord stores a separate copy of the review message and attached answers. Withdrawing an application does not erase its history, and deleting database records does not automatically remove the Discord copy.</p><h2>ACCESS, EXPORT &amp; DELETION</h2><p>Your profile page can export your profile and application records. Staff can review application data only through authorized backend access. Deletion is a staff-assisted request in this release, not an automatic deletion button. The owner must publish an accessible contact route and document record retention before launch.</p><h2>NO HIDDEN PRIVATE FILES</h2><p>Public HTML and repository files are not private storage. Member and staff resource content belongs in the access-controlled database. External documents and files must have their own appropriate access controls.</p><div class="button-row" style="margin-top:25px">'+btn('Open account settings','portal.html#profile')+btn('Contact support',attr='data-link="support"')+'</div></article>'))
page('404.html','Page not found','The requested page could not be found.',hero('A WRONG TURN.','The page you are looking for is not here. Head back to the city’s front door.','404','<div class="button-row">'+btn('Back to Home','index.html',True)+btn('Open Core Hub','core-hub.html')+'</div>'))
